import pandas as pd
gene_dict = [TP53_dict,MYC_dict,Bcl2_dict,ABCB1_dict,EGFR_dict,ATP5F1A_dict,HSPA5_dict,HSPA8_dict,PFN1_dict,PGK1_dict,
             PSMA1_dict,RAN_dict,RPL8_dict,RPS6_dict,SOD1_dict,TPI1_dict,TUBB_dict,VCP_dict,YWHAB_dict,YWHAE_dict]
df = pd.DataFrame(gene_dict)

GC = df["Sequence"].apply(GC_content)
Nucleotide = df["Sequence"].apply(count_nucleotide)

df["GC_%"] = GC
df["Nucleotides"] = Nucleotide

df["A"] = df["Nucleotides"].apply(lambda x : x["A"])
df["T"] = df["Nucleotides"].apply(lambda x : x["T"])
df["G"] = df["Nucleotides"].apply(lambda x : x["G"])
df["C"] = df["Nucleotides"].apply(lambda x : x["C"])

print(df)
print(df["group"].value_counts())

baseline_mean = df[df["group"]=="baseline"]["GC_%"].mean()
baseline_std = df[df["group"]=="baseline"]["GC_%"].std()
baseline_min = df[df["group"]=="baseline"]["GC_%"].min()
baseline_max = df[df["group"]=="baseline"]["GC_%"].max()

print("baseline_mean : ",baseline_mean)
print("baseline_std : ",baseline_std)
print("baseline_min : ",baseline_min)
print("baseline_max : ",baseline_max)

gene_GC = df[df["group"]=="TNBC"]["GC_%"]
z_score = ((gene_GC - baseline_mean)/baseline_std)
print(z_score)

import matplotlib.pyplot as plt
from matplotlib.patches import Patch

x = df["GC_%"]
y = df["Gene"]

Group = df["group"]
Colors = []
for data in Group:
    if data == "TNBC":
        color = "firebrick"
    else:
        color = "steelblue"  
    Colors.append(color)

plt.barh(y,x, color=Colors)
plt.xlabel("GC Content%")
plt.ylabel("Gene Name")
plt.title("GC_content comparison between TNBC and Baseline genes")

TNBC_patch = Patch(color="firebrick", label="TNBC")
Baseline_patch = Patch(color="steelblue", label="Baseline")
plt.legend(handles=[TNBC_patch,Baseline_patch], loc="upper right")

plt.axvspan(baseline_mean - baseline_std, baseline_mean + baseline_std, alpha=0.2, color="green")
plt.text(baseline_mean, 19.7, "±1 SD from baseline mean", ha="center", fontsize=9)

plt.savefig("gc_content_comparison.png", dpi=300, bbox_inches="tight")
plt.show()
